-- Integrated credentials use the portal database. No existing portal rows change.
-- Text payloads retain exact signing bytes; issuer keys remain private files.
BEGIN;
CREATE TABLE credential_workspaces(id TEXT PRIMARY KEY,key_id TEXT NOT NULL);
CREATE TABLE credential_metadata(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(workspace,key));
CREATE TABLE credential_badges(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id TEXT NOT NULL,learner TEXT NOT NULL,course TEXT NOT NULL,rule_version TEXT NOT NULL,issued_at TEXT NOT NULL,credential TEXT NOT NULL,signature TEXT NOT NULL,evidence TEXT NOT NULL,shared INTEGER NOT NULL DEFAULT 0 CHECK(shared IN (0,1)),revoked_at TEXT,revocation_reason TEXT,badge_version_id TEXT,course_mapping_id TEXT,award_key TEXT,PRIMARY KEY(workspace,id),UNIQUE(workspace,learner,course,rule_version));
CREATE TABLE credential_audit(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,at TEXT NOT NULL,action TEXT NOT NULL,badge_id TEXT,actor TEXT NOT NULL);
CREATE TABLE credential_badge_drafts(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id TEXT NOT NULL,revision INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,design TEXT NOT NULL,PRIMARY KEY(workspace,id));
CREATE TABLE credential_badge_versions(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id TEXT NOT NULL,draft_id TEXT NOT NULL,draft_revision INTEGER NOT NULL,status TEXT NOT NULL,design_json TEXT NOT NULL,artwork_svg TEXT NOT NULL,approved_at TEXT NOT NULL,approved_by TEXT NOT NULL,activated_at TEXT,archived_at TEXT,PRIMARY KEY(workspace,id),UNIQUE(workspace,draft_id,draft_revision),FOREIGN KEY(workspace,draft_id) REFERENCES credential_badge_drafts(workspace,id));
CREATE TABLE credential_course_mappings(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id TEXT NOT NULL,badge_version_id TEXT NOT NULL,rule_json TEXT NOT NULL,rule_hash TEXT NOT NULL,verification_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),created_at TEXT NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(workspace,id),UNIQUE(workspace,badge_version_id,rule_hash),FOREIGN KEY(workspace,badge_version_id) REFERENCES credential_badge_versions(workspace,id));
CREATE TABLE credential_publishing_activity(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,at TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,actor TEXT NOT NULL);
CREATE TABLE credential_award_batches(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id TEXT NOT NULL,actor TEXT NOT NULL,method TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,version_id TEXT NOT NULL,snapshot_hash TEXT NOT NULL,state TEXT NOT NULL,rows_json TEXT NOT NULL,completed_at TEXT,certificate_json TEXT,PRIMARY KEY(workspace,id));
CREATE TABLE credential_certificate_templates(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id TEXT NOT NULL,revision INTEGER NOT NULL,name TEXT NOT NULL,design_json TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(workspace,id));
CREATE TABLE credential_certificates(workspace TEXT NOT NULL REFERENCES credential_workspaces(id),id TEXT NOT NULL,source_id TEXT NOT NULL,badge_id TEXT NOT NULL,learner TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL,snapshot_json TEXT NOT NULL,signature TEXT NOT NULL,PRIMARY KEY(workspace,id),UNIQUE(workspace,source_id,badge_id));
CREATE UNIQUE INDEX credential_mapped_award_key ON credential_badges(workspace,award_key) WHERE award_key IS NOT NULL;
CREATE INDEX credential_learner_awards ON credential_badges(workspace,learner,issued_at);
CREATE FUNCTION credential_snapshot_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Published credential snapshots are immutable'; END; $$;
CREATE TRIGGER immutable_badge_version BEFORE UPDATE OF draft_id,draft_revision,design_json,artwork_svg ON credential_badge_versions FOR EACH ROW EXECUTE FUNCTION credential_snapshot_immutable();
CREATE TRIGGER immutable_course_mapping BEFORE UPDATE OF badge_version_id,rule_json,rule_hash,verification_json ON credential_course_mappings FOR EACH ROW EXECUTE FUNCTION credential_snapshot_immutable();
CREATE TRIGGER immutable_certificate BEFORE UPDATE ON credential_certificates FOR EACH ROW EXECUTE FUNCTION credential_snapshot_immutable();
COMMIT;
